/* eslint-disable @typescript-eslint/no-explicit-any */
import { Component, createSignal, type Accessor, type ComponentProps, type Setter } from "solid-js";
import { createComponent } from "solid-js/web";

import { ComponentUtilities } from "#core/ui-next/utilities/component-utilities.js";
import { PreloadedImage } from "#core/ui-next/utilities/image-cache.js";
import { PreloadedStyle } from "#core/ui-next/utilities/style-cache.js";

type WrappedComponent<T extends Record<string, any>, U extends Component<T>> = {
	factoryName: string;
	factory: Accessor<U>;
	setFactory: Setter<U>;
	overridePriority: number;
	cachedImages: Promise<PromiseSettledResult<PreloadedImage>[]> | undefined;
	cachedStyles: Promise<PreloadedStyle[]> | undefined;
} & U;

export const [componentRegistered, setComponentRegistered] = createSignal<WrappedComponent<any, any>>();

export interface ComponentOptions<T extends Record<string, any>, U extends Component<T>> {
	// The name of the component - only used for registration and overrides
	name: string;
	// The component factory function
	createInstance: U;
	// The component registered with the highest override priority will be used. Default: 0
	overridePriority?: number;
	// An optional list of stylesheet urls to load
	styles?: string[];
	// An optional list of image urls to load
	images?: string[];
}

/**
 * The Component Registry
 *
 * The component registry can be used to preload component resources and to generate overridable components
 *
 * To generate a component overrides, define a new component with the same name and higher priority:
 * ```tsx
 * export const OriginalComponent = ComponentRegistry.register("Original", Original);
 * <OriginalComponent /> // This will be an instance of OriginalComponent
 * ...
 * export const OriginalOverrideComponent = ComponentRegistry.register("Original", OriginalOverride, 1);
 * <OriginalComponent /> // This will be an instance of OriginalOverrideComponent
 * <OriginalOverrideComponent /> // This will be an instance of OriginalOverrideComponent
 * ```
 * In the example above, both OriginalComponent and OriginalOverrideComponent will create an OriginalOverrideComponent when called.
 */
class ComponentRegistryImpl {
	componentFactories = new Map<string, unknown>();

	/**
	 * Registers a component with the component registry.
	 * Components can be overriden (for example, by mods) by setting a higher priority in options
	 * See {@link ComponentRegistryImpl} for more info
	 * ```ts
	 * import exampleStyle from "component/example-component.scss?url";
	 * export Example = RegisterComponent({
	 *   name: "ExampleComponent",
	 *   createInstance: ExampleComponent,
	 *   images: ["blp:example-image.png", ...],
	 *   styles: [exampleStyle, ...]
	 *   overridePriority: 0
	 * })
	 * ```
	 * @param options The component options to set
	 * @returns The registered overridable component
	 */
	public register<T extends Record<string, any>, U extends Component<T>>(options: ComponentOptions<T, U>): U;
	/**
	 * A simplified way to register a component if no options are required
	 * ```ts
	 * export Example = RegisterComponent("ExampleComponent", ExampleComponent);
	 * ```
	 * @param name The name of the component - only used for registration and overrides
	 * @param createInstance The component factory function
	 * @param overridePriority The component registered with the highest override priority will be used. Default: 0
	 * @returns The registered overridable component
	 */
	public register<T extends Record<string, any>, U extends Component<T>>(
		name: string,
		createInstance: U,
		overridePriority?: number,
	): U;
	public register<T extends Record<string, any>, U extends Component<T>>(
		optionsOrName: ComponentOptions<T, U> | string,
		createInstance?: U,
		overridePriority?: number,
	): U {
		let name = optionsOrName;
		let factory = createInstance;
		let cachedImages: Promise<PromiseSettledResult<PreloadedImage>[]> | undefined;
		let cachedStyles: Promise<PreloadedStyle[]> | undefined;

		if (typeof optionsOrName != "string") {
			name = optionsOrName.name;
			factory = optionsOrName.createInstance;
			overridePriority = optionsOrName.overridePriority;

			if (optionsOrName?.images) {
				cachedImages = ComponentUtilities.preloadImages(...optionsOrName.images);
			}

			if (optionsOrName?.styles) {
				cachedStyles = ComponentUtilities.loadStyles(...optionsOrName.styles);
			}
		}

		let wrappedComponentFactory = this.componentFactories.get(name as string) as WrappedComponent<T, U>;

		overridePriority ??= 0;

		if (wrappedComponentFactory) {
			if (wrappedComponentFactory.overridePriority <= overridePriority) {
				wrappedComponentFactory.overridePriority = overridePriority;
				wrappedComponentFactory.setFactory(() => factory!);
			}
		} else {
			wrappedComponentFactory = this.wrapComponentFactory(
				name as string,
				factory!,
				overridePriority,
				cachedImages,
				cachedStyles,
			);
		}

		setComponentRegistered(() => wrappedComponentFactory);

		return wrappedComponentFactory;
	}

	/**
	 * Gets a registered component from the component registry.
	 * Will return a wrapper that points the component factory with the highest override priority.
	 * @param name The name of the component to get
	 * @returns The registered component or undefined if no registration was not found
	 */
	public get<T extends Record<string, any>, U extends Component<T>>(name: string) {
		return this.componentFactories.get(name) as WrappedComponent<T, U> | undefined;
	}

	/**
	 * Returns a promise that resolved when all styles and images are preloaded for a give list of components
	 * @param components The list of components to preload styles and images for
	 * @returns A promise that resolves when all associated styles and images are loaded
	 */
	public preloadComponents(...components: WrappedComponent<any, any>[]) {
		return Promise.all([
			...components.map((c) => c.cachedImages ?? []),
			...components.map((c) => c.cachedStyles ?? []),
		]);
	}

	private wrapComponentFactory<T extends Record<string, any>, U extends Component<T>>(
		name: string,
		factory: U,
		overridePriority: number,
		cachedImages: Promise<PromiseSettledResult<PreloadedImage>[]> | undefined,
		cachedStyles: Promise<PreloadedStyle[]> | undefined,
	) {
		const [getFactory, setFactory] = createSignal<U>(factory);

		const wrappedFactory = (
			import.meta.hot
				? (props: ComponentProps<U>) => <>{createComponent(getFactory(), props)}</>
				: (props: ComponentProps<U>) => getFactory()(props) //eslint-disable-line solid/reactivity
		) as WrappedComponent<T, U>;

		wrappedFactory.factoryName = name;
		wrappedFactory.factory = getFactory;
		wrappedFactory.setFactory = setFactory;
		wrappedFactory.overridePriority = overridePriority;
		wrappedFactory.cachedImages = cachedImages;
		wrappedFactory.cachedStyles = cachedStyles;

		this.componentFactories.set(name, wrappedFactory);

		return wrappedFactory as WrappedComponent<T, U>;
	}
}

export const ComponentRegistry = new ComponentRegistryImpl();
